var canvas = GameObject.Find("Canvas_Lobby");
var sb = new System.Text.StringBuilder();
void Dump(Transform t, int indent) {
    var btn = t.GetComponent<UnityEngine.UI.Button>();
    var tmp = t.GetComponent<TMPro.TextMeshProUGUI>();
    string info = "";
    if (btn != null) info += " [BTN]";
    if (tmp != null) info += $" [TMP: '{tmp.text}']";
    sb.AppendLine(new string(' ', indent * 2) + t.name + info);
    foreach (Transform c in t) Dump(c, indent + 1);
}
Dump(canvas.transform, 0);
return sb.ToString();
